import{c as d,Q as r,j as o,m as a}from"./chunks/framework.BPKcPtvA.js";const e="/screenshots/library.png",s="/screenshots/library-card.png",l="/screenshots/library-bulk.png",i="/screenshots/import-chooser.png",n="/screenshots/import-standalone.png",c="/screenshots/import-standalone-category.png",h="/screenshots/notifications.png",B=JSON.parse('{"title":"ライブラリ画面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/library.md","filePath":"guide/library.md","lastUpdated":1786391114000}'),g={name:"guide/library.md"};function p(b,t,u,O,m,T){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ライブラリ画面" tabindex="-1">ライブラリ画面 <a class="header-anchor" href="#ライブラリ画面" aria-label="Permalink to &quot;ライブラリ画面&quot;">​</a></h1><p>アプリ起動時に最初に表示される画面で、BOOTH の購入・ギフト・無料ダウンロードから 取り込んだ商品と、手動で追加したアイテムを 1 つの一覧で表示します。</p><h2 id="主な構成" tabindex="-1">主な構成 <a class="header-anchor" href="#主な構成" aria-label="Permalink to &quot;主な構成&quot;">​</a></h2><p><img src="'+e+'" alt="ライブラリ画面 — 上部ツールバー、カード一覧、右下のボタン"></p><p>上部に <strong>ツールバー</strong>、その下に <strong>カード一覧</strong>、右下に <strong>通知ベルと手動追加ボタン</strong> があります。ダウンロードキューは上部ツールバーから開きます。</p><blockquote><p>画面内の商品名・ショップ名はデモ用の架空データです。</p></blockquote><h2 id="ツールバー" tabindex="-1">ツールバー <a class="header-anchor" href="#ツールバー" aria-label="Permalink to &quot;ツールバー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ボタン</th><th>動作</th></tr></thead><tbody><tr><td>🔄 ライブラリの商品情報を更新</td><td>BOOTH 商品の情報 (商品名・画像・ファイルなど) を 1 件ずつ順に取り直します (途中でキャンセル可)。起動時の自動取得が ON のときは、先に BOOTH ライブラリを確認して新しく買った商品も取り込みます</td></tr><tr><td>🔁 一括再ダウンロード</td><td>ダウンロードに失敗した / 期限切れになったファイルがあるときだけ現れます (件数バッジ付き)。押すと確認のうえ、対象を 1 件ずつ順に再ダウンロードします (途中でキャンセル可)</td></tr><tr><td>🔍 検索</td><td>商品名 / ショップ名 / BOOTH 商品 ID / ファイル名を部分一致で検索。<code>shop:</code> / <code>tag:</code> / <code>memo:</code> と <code>-</code> 除外を組み合わせられ、直近 20 件は入力候補として表示</td></tr><tr><td>↕ 並び</td><td>🕒 最近開いた のほか、追加日 / 購入日 / 商品名 / ショップ名 / BOOTH 商品 ID を昇順・降順で切替</td></tr><tr><td>▦ グループ表示</td><td>選んだ軸で見出し付きのセクションに分けて表示 (後述)</td></tr><tr><td>▽ 絞り込み</td><td>★ お気に入り / 🕒 最近開いた / BOOTH カテゴリ / 状態 (非公開・販売終了・R-18 など) / カスタムカテゴリ / <strong>スキリスト</strong> (スキリストにも入れている商品だけ、またはリストごと・未分類含む) / タグ をチェックで複数選択。上部の「タグ・カテゴリ検索…」欄で候補をしぼり込め、条件の保存も可</td></tr><tr><td>⊞ サイズ</td><td>カード一覧の 大 / 中 / 小 + カスタム (横・縦のスライダー独立)</td></tr><tr><td>⋯ メニュー</td><td>表示オプション: R-18 / 📦 アーカイブ / 🗑️ ゴミ箱 の表示切替と、「ダウンロード済を優先」「★ お気に入りを優先」(並びで上に集める) のオン/オフ</td></tr><tr><td>☑ 選択モード</td><td>複数のアイテムを選んで一括操作するモードに切替</td></tr><tr><td>💾 ダウンロードキュー</td><td>ダウンロード状況のパネルを開く (後述)</td></tr></tbody></table><h3 id="複合検索" tabindex="-1">複合検索 <a class="header-anchor" href="#複合検索" aria-label="Permalink to &quot;複合検索&quot;">​</a></h3><p>空白で区切った検索語はすべて AND になります。空白を含む連続した語句は <code>&quot;Blue Avatar&quot;</code> のように <code>&quot;</code> で囲みます。英字の大小は区別しません。</p><table tabindex="0"><thead><tr><th>入力</th><th>検索対象 / 動作</th></tr></thead><tbody><tr><td><code>avatar blue</code></td><td>商品名 / ショップ名 / 商品 ID / ファイル名のどこかに、両方の語がある商品</td></tr><tr><td><code>shop:&quot;Alice Studio&quot;</code></td><td>ショップ名または BOOTH subdomain</td></tr><tr><td><code>tag:VRChat</code></td><td>BOOTH の商品タグ</td></tr><tr><td><code>memo:確認済み</code></td><td>アプリで付けたメモ全文</td></tr><tr><td><code>-memo:旧版</code></td><td>メモに「旧版」を含む商品を除外 (<code>-shop:</code> / <code>-tag:</code> / 通常語の <code>-</code> も同様)</td></tr></tbody></table><p>例: <code>avatar shop:&quot;Alice Studio&quot; tag:VRChat -memo:旧版</code> と入力すると、 通常検索・ショップ・タグをすべて満たし、メモに「旧版」がない商品だけを表示します。</p><h3 id="グループ表示" tabindex="-1">グループ表示 <a class="header-anchor" href="#グループ表示" aria-label="Permalink to &quot;グループ表示&quot;">​</a></h3><p>▦ ボタンで、一覧を選んだ軸ごとの見出し付きセクションに分けて表示できます。軸は ショップ / BOOTH カテゴリ / カスタムカテゴリ / タグ / スキリスト / 取得元 / お気に入り / 最近開いた / 各状態 (更新あり・アーカイブ・ゴミ箱・非公開・販売終了・R-18) から 選べます。「グループ化なし」で通常の一覧に戻ります。 選択肢に出す軸は <a href="/guide/settings#グループ表示で選べる軸">設定 → グループ表示で選べる軸</a> で変えられます (はじめは「あり / なし」の 2 つに分かれるだけの軸は出ません)。</p><ul><li><strong>見出しをクリックで開閉</strong> できます (件数付き)。開閉の状態は軸ごとに記憶します。 Alt を押しながらクリックすると、子カテゴリの見出しもまとめて同じ状態に開閉します。</li><li>見出しにカーソルを乗せると ▶ の横にチェックボックスが現れ、<strong>そのセクションの 商品をまとめて選択</strong>できます (もう一度押すと解除)。親カテゴリの見出しでは 子カテゴリの分も含めて選択されます。</li><li>見出しを<strong>右クリック</strong>すると、そのセクションの商品に対する一括操作メニュー (まとめてダウンロード・カテゴリ追加 など) が開きます。メニューを開いただけ では選択は変わらず、操作を選んだ時点でそのセクションが選択されます。</li><li><strong>BOOTH カテゴリ</strong>は親カテゴリの中に子カテゴリの見出しが入る 2 段構成です。</li><li>カスタムカテゴリ・タグ・スキリスト・取得元のように <strong>1 つの商品が複数に属する軸</strong> では、その商品のカードが該当する各セクションに繰り返し表示されます (例: 無料ダウンロードにあり、かつアプリで受信もした商品は両方に出ます)。</li><li>絞り込み・検索・並び順はグループ表示中もそのまま効きます (セクション内で並びます)。</li></ul><h2 id="カード-1-枚" tabindex="-1">カード 1 枚 <a class="header-anchor" href="#カード-1-枚" aria-label="Permalink to &quot;カード 1 枚&quot;">​</a></h2><p><img src="'+s+'" alt="ライブラリのカード 1 枚 — サムネ・商品名・ショップ名・各種タグ・ファイル数"></p><p>1 枚のカードに以下が並びます:</p><ul><li><strong>商品サムネ</strong> (左) と <strong>商品名</strong></li><li><strong>ショップ名</strong> (アイコン付き)</li><li><strong>各種タグ</strong> — BOOTH カテゴリ / R-18 / 価格など</li><li><strong>由来バッジ</strong> — 購入 / ギフト / 手動 / 無料DL (サムネ下)。<code>無料DL</code> は BOOTH の「無料ダウンロード履歴」にあるアイテムに付き、ライブラリ取得時に 自動で拾われます (他の由来バッジと重ねて表示)</li><li><strong>ファイル数</strong> (例: <code>3 / 5 ファイル</code>) とダウンロードアイコン</li><li><strong>★ お気に入り</strong> (右上、カーソルを乗せると出現)</li><li>ダウンロード中は下端に <strong>進捗バー</strong> が伸びます</li><li>サムネイルにカーソルを約 0.6 秒乗せると拡大プレビューが出て (設定で OFF 可)、 サムネイルを右クリック →「画像を拡大表示」で画面いっぱいに表示できる</li></ul><h3 id="クリック挙動" tabindex="-1">クリック挙動 <a class="header-anchor" href="#クリック挙動" aria-label="Permalink to &quot;クリック挙動&quot;">​</a></h3><table tabindex="0"><thead><tr><th>キー操作</th><th>動作</th></tr></thead><tbody><tr><td>左クリック</td><td>商品詳細画面を開く</td></tr><tr><td><strong>Ctrl</strong> + 左クリック</td><td>一括選択モードに入る + このカードを選択</td></tr><tr><td><strong>Shift</strong> + 左クリック</td><td>BOOTH 商品ページを外部ブラウザで開く</td></tr><tr><td>★ クリック</td><td>お気に入りの切替</td></tr><tr><td>右クリック</td><td>メニュー (ダウンロード / カテゴリ / アーカイブ / ゴミ箱 など)</td></tr><tr><td><strong>Shift</strong> + 右クリック</td><td>上記 + 詳しい項目 (<code>🔄 商品情報を更新</code> / <code>📤 ファイルをフォルダにコピー…</code> / <code>⚠️ 完全削除 (ゴミ箱経由なし)</code>) を別の区切りで表示</td></tr><tr><td><strong>Ctrl</strong> + 右クリック</td><td>この商品の未取得ファイルをダウンロード (メニューを開かず即実行。非公開・対象外の旧版は除く)</td></tr><tr><td><strong>Ctrl</strong> + <strong>Shift</strong> + 右クリック</td><td>このアイテムを確認なしでゴミ箱へ (通知の「元に戻す」で復元可)</td></tr></tbody></table><p>(キー操作は <strong>Shift</strong> や <strong>Ctrl</strong> を押すと画面左下に動的にヒントが出ます — 詳細は <a href="/guide/keyboard-shortcuts">キーボードショートカット</a>)</p><div class="tip custom-block"><p class="custom-block-title">BOOTH カテゴリの変更</p><p>右クリック → <code>🏷️ カテゴリを編集</code> のダイアログで、カスタムカテゴリと一緒に <strong>BOOTH カテゴリ</strong>も変更できます (手動で追加した商品への付与も同じ場所)。 一括選択モードの右クリックメニューからは、選択中の商品にまとめて設定できます。 ここで変更したカテゴリは、商品情報を更新しても上書きされずに残ります。</p></div><div class="tip custom-block"><p class="custom-block-title">商品情報の更新ですること</p><p><code>🔄 商品情報を更新</code> を押すと、商品名や画像などの情報を BOOTH から取り直すだけでなく、 その商品に増えていた新しいファイルがあれば一緒に登録し、購入した注文の情報が抜けていれば BOOTH の購入履歴を確認して補い直します。あわせて、商品からその種類 (バリエーション) ごと 無くなったファイルや、無料で配っていたファイルの配布が終わっていた場合には、この再取得の ときに自動で「非公開」タグが付きます。有料ファイル単位で配布が終わっていた場合も、 ダウンロードを試みたときに配布終了 (404) が分かれば、その場ですぐ「非公開」タグが付きます。</p></div><h3 id="状態の見分け" tabindex="-1">状態の見分け <a class="header-anchor" href="#状態の見分け" aria-label="Permalink to &quot;状態の見分け&quot;">​</a></h3><ul><li>通常 (= 1 つ以上ダウンロード済み): 標準色</li><li>全ファイル未ダウンロード: 全体的に暗く表示</li><li>ダウンロード中: 下端に進捗バーが伸びる</li><li>アーカイブ (= 古いものを別途 ZIP 圧縮済み): <code>📦 アーカイブ</code> タグ + 暗く表示</li><li>ゴミ箱: <code>🗑️ ゴミ箱</code> タグ (デフォルトでは非表示、設定で表示)</li><li>削除済み (= BOOTH 側から消えた): <code>🚫 非公開</code> タグ</li><li>販売終了 (= BOOTH で販売が終了した): <code>販売終了</code> タグ (ダウンロード済みのファイルはそのまま使えます)</li><li>更新あり (= 出品者が新しいファイルを追加した): <code>📦 更新あり</code> タグ (詳細を開くと確認済みになる)</li><li>最近追加 (= 新しく買った・受け取った・手動で追加した): <code>🆕 最近追加</code> タグ (7 日で自動的に消える)</li></ul><h2 id="一括選択モード" tabindex="-1">一括選択モード <a class="header-anchor" href="#一括選択モード" aria-label="Permalink to &quot;一括選択モード&quot;">​</a></h2><p>ツールバー右の ☑ ボタン、または <strong>Ctrl + 左クリック</strong> で入ります。</p><p><img src="'+l+'" alt="一括選択モード — 全カードにチェック、上部に選択件数バー、下部に操作ドック"></p><ul><li>カード左上にチェックボックスが出る</li><li><strong>上部バー</strong>: 「N 件選択」表示 + 「すべて選択」「選択解除」「× (モード終了)」ボタン</li><li><strong>下部の操作ドック</strong> (画面下中央に浮かぶ): 選択したアイテムへの一括操作をアイコンで実行<table tabindex="0"><thead><tr><th>アイコン</th><th>動作</th></tr></thead><tbody><tr><td>全てダウンロード</td><td>選択アイテムの未ダウンロードのファイルをまとめてダウンロード予約</td></tr><tr><td>カテゴリを編集</td><td>選択アイテムに BOOTH カテゴリの設定・カスタムカテゴリの追加をまとめて</td></tr><tr><td>アーカイブする / 解除</td><td>選択アイテムをアーカイブ (ZIP 圧縮) / 解除</td></tr><tr><td>ファイルをフォルダにコピー</td><td>選択アイテムのファイルを指定フォルダへまとめてコピー</td></tr><tr><td>おすすめリストとしてエクスポート</td><td>選択アイテムを Markdown / JSON でエクスポート。カスタムカテゴリやメモを含めるかも選べます (選択は次回も記憶)</td></tr><tr><td>ゴミ箱に移動</td><td>選択アイテムをゴミ箱へ</td></tr><tr><td>ドックのボタンは、選択内容に応じて実行できないものが自動で無効になります。</td><td></td></tr></tbody></table></li><li><strong>Ctrl + I</strong> で選択を反転できます (専用ボタンはなく、キーボードのみ)</li><li>右クリック → 同じ一括メニューを右クリックメニューでも表示 (件数併記)。<strong>ゴミ箱の商品を選んでいるとき</strong>は「♻️ ゴミ箱から戻す」「⚠️ 完全削除」も出ます</li><li><strong>Esc</strong> または ☑ 再クリック / Ctrl + 右クリックで終了</li></ul><div class="tip custom-block"><p class="custom-block-title">旧バージョンの除外</p><p>設定の「旧バージョンをファイル数・一括ダウンロードに含めない」(デフォルト ON) が 効いていると、「全てダウンロード」は各アイテムの<strong>現行版のみ</strong>を対象にします。 旧版は詳細画面から個別にダウンロードできます。</p></div><h2 id="右下のボタン" tabindex="-1">右下のボタン <a class="header-anchor" href="#右下のボタン" aria-label="Permalink to &quot;右下のボタン&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ボタン</th><th>動作</th></tr></thead><tbody><tr><td>🔔</td><td>通知ベル (後述、新着・更新・値下げ・アプリ更新 の履歴を表示)</td></tr><tr><td>＋</td><td>手動追加 (URL の貼り付け / 既存アイテムに追加 / 単独アイテムの 3 通り)</td></tr></tbody></table><h3 id="ダウンロード状況のパネル-💾" tabindex="-1">ダウンロード状況のパネル (💾) <a class="header-anchor" href="#ダウンロード状況のパネル-💾" aria-label="Permalink to &quot;ダウンロード状況のパネル (💾)&quot;">​</a></h3><p>上部ツールバーの 💾 ボタンから開き、進行中のダウンロードを区分ごとにまとめて表示します:</p><ul><li><strong>進行中</strong> — 実際にダウンロード中 (進捗バー付き)。一時停止 / キャンセルできます</li><li><strong>解凍中</strong> — ダウンロードは終わって ZIP を展開している最中。ダウンロードとは 分けて表示されるので、「終わったのにキューに残っている」ように見えません。 展開先を壊さないようにするため、解凍が完了するまで中止できません</li><li><strong>一時停止</strong> — 続きから再開できます</li><li><strong>待機中</strong> — 空き次第ダウンロードされます。ドラッグで順番を入れ替えられます</li></ul><p>下部のスライダーで <strong>同時ダウンロード数</strong> を変えられます。</p><p>同じダウンロードは、どの画面からでも開ける <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> にも表示されます。 そこでは進捗の確認と中止 (解凍中を除く)、アプリを開いてから完了・失敗・中止した履歴の確認ができます。 一時停止・再開、待機順、同時ダウンロード数はこのダウンロード状況パネルで操作します。</p><p>「全てダウンロード」など複数まとめて予約したときは、<strong>全件がすぐに「待機中」に 並びます</strong> (URL の準備は各ファイルのダウンロード直前に裏で行うため、一覧に出る までに待たされません)。</p><h3 id="手動追加-の-3-通り" tabindex="-1">手動追加 (＋) の 3 通り <a class="header-anchor" href="#手動追加-の-3-通り" aria-label="Permalink to &quot;手動追加 (＋) の 3 通り&quot;">​</a></h3><p>＋ を押すと「ファイルを追加」の選択画面が開き、3 つの取り込み方法を選べます。</p><p><img src="'+i+'" alt="ファイルを追加の選択画面 — BOOTH URL / 既存アイテムに追加 / 単独アイテムとして作る"></p><table tabindex="0"><thead><tr><th>方法</th><th>用途</th></tr></thead><tbody><tr><td>BOOTH URL から</td><td>商品ページの URL を貼ると、その商品のダウンロードできるファイルを登録</td></tr><tr><td>既存アイテムに追加</td><td>ライブラリの既存アイテムを検索し、その下に手元のファイルを足す</td></tr><tr><td>単独アイテムとして作る</td><td>BOOTH と紐付かない手元のファイルを、情報付きでそのまま登録</td></tr></tbody></table><p>「BOOTH URL から」で登録したファイルは、設定の <a href="/guide/settings#追加した商品をすぐダウンロード">追加した商品をすぐダウンロード</a> が ON (デフォルト) なら、登録と同時にダウンロードが始まります。 BOOTH の商品ページ URL をコピーした状態でこの画面を開くと、URL 欄に自動で貼り付けられます。</p><p><strong>単独アイテム</strong> は、名前 / ショップ / サムネ画像に加えて <strong>BOOTH カテゴリ</strong> (公式カテゴリの サブカテゴリのみ選択、親は自動付与) と <strong>カスタムカテゴリ</strong> を付けられます。右側の カードプレビューが入力に追従し、ライブラリ上での見え方をその場で確認できます。</p><p><img src="'+n+'" alt="単独アイテム作成 — 入力に追従するカードプレビュー付き"></p><p>BOOTH カテゴリは公式カテゴリから取得した候補から選びます (親カテゴリは見出しで、 選べるのは子のサブカテゴリのみ。親は選んだときに自動で一緒に付与されます)。</p><p><img src="'+c+'" alt="BOOTH カテゴリの選択 — 親の見出し + 子のサブカテゴリの一覧"></p><h2 id="通知パネル-🔔" tabindex="-1">通知パネル (🔔) <a class="header-anchor" href="#通知パネル-🔔" aria-label="Permalink to &quot;通知パネル (🔔)&quot;">​</a></h2><p>右下の 🔔 ボタンで開くパネルに、以下の通知が時系列で並びます。 長いショップ名 / 商品名 / ファイル名は省略されず折り返してすべて表示されます。 各行にカーソルを乗せると「クリックで○○を開きます」のヒントが出ます。 各行の右端の × でその通知だけを消せます。パネル右上の「履歴消去」で全通知をまとめて消せます。</p><p><img src="'+h+'" alt="通知パネル — ショップ新着・値下げ・アイテム更新・アップデートなど"></p><table tabindex="0"><thead><tr><th>種類</th><th>サムネ</th><th>内容</th><th>クリック挙動</th></tr></thead><tbody><tr><td>🏪 ショップ新着</td><td>アイテムサムネ</td><td>フォロー中ショップに新作</td><td>BOOTH 商品ページを外部ブラウザで開く</td></tr><tr><td>🛒 販売開始</td><td>アイテムサムネ</td><td>スキリストや新着で見つけた<strong>販売前 (予約) の商品が販売開始</strong>になったとき。販売開始日時が分かるものは、その時刻になったら知らせます</td><td>BOOTH 商品ページを外部ブラウザで開く</td></tr><tr><td>📦 アイテム更新</td><td>アイテムサムネ</td><td>購入済みアイテムに新しいファイルが追加。1 回の取得で同じ商品に複数ファイルが増えたときは 1 件にまとめ、ファイル名をすべて並べます</td><td>アプリ内で詳細画面を開く</td></tr><tr><td>💸 値下げ</td><td>アイテムサムネ</td><td>スキリスト商品が値下げ。複数のバリエーションが同時に下がったときは、見出しに <code>(N 種値下げ)</code> と件数が付き、どのバリエーションがいくらに下がったかを 1 件ずつすべて並べます</td><td>BOOTH 商品ページを外部ブラウザで開く</td></tr><tr><td>📣 運営からのお知らせ</td><td>アプリアイコン</td><td>このアプリの開発・運営からのお知らせ</td><td>リンクが付いているときはクリックで外部ブラウザで開く</td></tr><tr><td>📦 アップデートあり</td><td>アプリアイコン</td><td>アプリ自身の新バージョン</td><td>クリックで更新を開始。自動更新できない形式ではリリースページを開く (詳細は <a href="/guide/settings#アップデート">設定 &gt; アップデート</a>)</td></tr></tbody></table><h2 id="非公開アイテムの扱い" tabindex="-1">非公開アイテムの扱い <a class="header-anchor" href="#非公開アイテムの扱い" aria-label="Permalink to &quot;非公開アイテムの扱い&quot;">​</a></h2><p>BOOTH 側で削除 / 非公開化されたアイテムは、カード上の <strong>「BOOTH を開く」</strong> 系の操作を 試みても外部ブラウザを開かず、代わりに 🚫 のメッセージで「この商品は非公開のため開けません」と 知らせます (リンク切れでブラウザにエラーページを出さないため)。</p><p>非公開になったファイルは<strong>もう入手できない</strong>ので、カードのファイル数 (「○ / ○ ファイル」) には 数えません。詳細画面のファイル一覧でも、<strong>非公開でまだダウンロードしていない</strong>ファイル (＝もう手に入らず手元にも無いもの) は薄く表示して、持っているファイルと見分けやすくしています。</p><h2 id="自動取得" tabindex="-1">自動取得 <a class="header-anchor" href="#自動取得" aria-label="Permalink to &quot;自動取得&quot;">​</a></h2><p>設定で「起動時にライブラリを自動取得する」(デフォルト ON) のとき、起動後に バックグラウンドで BOOTH ライブラリを取得します。中断された場合は次回起動時に途中から再開します。 進み具合の確認や中止は <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> から行えます。</p>',57)])])}const f=d(g,[["render",p]]);export{B as __pageData,f as default};
